exercises.solution:
try:
    int("abc")
except ValueError:
    print("Invalid number")

try:
    print(10 / 0)
except ZeroDivisionError:
    print("Cannot divide by zero")

text = input()
try:
    print(int(text) * 2)
except ValueError:
    print("Not a number")

try:
    int("5")
except ValueError:
    print("bad")
else:
    print("OK")
finally:
    print("Done")

nums = [1, 2, 3]
try:
    print(nums[10])
except IndexError:
    print("Out of range")

d = {"a": 1}
try:
    print(d["b"])
except KeyError:
    print("No such key")

def check_age(age):
    if age < 0:
        raise ValueError("Age cannot be negative")

try:
    check_age(-5)
except ValueError as e:
    print(e)

class InsufficientFunds(Exception):
    pass

try:
    raise InsufficientFunds("Not enough money")
except InsufficientFunds as e:
    print(e)

def safe_divide(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None

print(safe_divide(8, 2), safe_divide(1, 0))

while True:
    text = input()
    try:
        n = int(text)
        break
    except ValueError:
        continue
print(f"Got {n}")
